#!/usr/bin/env python3
"""
Check that the fail-fast scope/desugar panic counts in
internal/frontend/synth_*.go match the pinned manifest
(R23-P1-1, REVIEW-2026-11-12-23).

The no-bridges gate (check_no_bridges.py, Rule 3) fails on ADDED panic
stubs, but a count can drift silently in either direction without any
single added line looking wrong: a retirement deletes stubs one file
at a time, a generator re-run re-adds them, and nobody notices the
total moved. This check pins the count + per-file list, so any drift
fails loudly here and the manifest diff in the same change is the
review surface for whether the drift is legitimate.

What is pinned: lines in internal/frontend/synth_*.go that are fail-fast
panic calls whose message carries a scope-limit or multi-result-desugar
phrase — the same phrases Rule 3 matches, imported from
check_no_bridges.py so the gate and the counts cannot drift apart.
A line matching both phrases counts under "scope" (the phrase the
review pinned); "desugar" counts only lines with a desugar phrase and
no scope phrase. Both the literal form (`panic("...")`) and the
generated-code literal form (`panic(\"...\")`, synth_math_big.go)
count: a generated literal IS the source of a generated panic.

What is NOT pinned here: the archive/mime subset
(synth_archive_tar.go, synth_archive_zip.go, synth_mime.go,
synth_mime_multipart.go, synth_mime_quotedprintable.go). Those files
are generated by internal/frontend/gen_synth_archive_mime.py and their
multi-result rows are pinned by check_mr_table_subset.py; a panic-count
change there rides along with a generator re-run, not with a hand edit.
Rule 3 still fails on any ADDED scope/desugar panic in those files —
the gate covers additions everywhere; this manifest covers drift
outside archive/mime.

Usage:
  python3 .github/scripts/check_scope_panic_inventory.py
      Compare the live tree against scope_panic_manifest.json; exit 1
      on any mismatch (with the per-file diff), exit 0 on match.
  python3 .github/scripts/check_scope_panic_inventory.py --regenerate
      Rewrite scope_panic_manifest.json from the live tree. Run ONLY
      when the drift is legitimate (a retirement, a generator re-run,
      a newly landed scope) and commit the regenerated manifest in the
      SAME change, so the count change is reviewed, not smuggled in.

The check NEVER passes vacuously: a missing/unparseable manifest, or
zero pinned lines in the live tree (regex drift or a moved synth dir),
fails loudly instead of skipping.
"""

import glob
import json
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
# GRAALGO_REPO overrides the repo root (same pattern as the GO env var
# in check_mr_table_subset.py): a lane working in a sparse checkout
# verifies the manifest against a full tree without copying files.
REPO = os.environ.get(
    "GRAALGO_REPO", os.path.dirname(os.path.dirname(HERE)))
SYNTH_DIR = os.path.join(REPO, "internal", "frontend")
MANIFEST = os.path.join(HERE, "scope_panic_manifest.json")

sys.path.insert(0, HERE)
import check_no_bridges as cnb

# Archive/mime files: generated by gen_synth_archive_mime.py, pinned by
# check_mr_table_subset.py (see module docstring) — excluded here.
EXCLUDED_FILES = {
    "synth_archive_tar.go",
    "synth_archive_zip.go",
    "synth_mime.go",
    "synth_mime_multipart.go",
    "synth_mime_quotedprintable.go",
}


def _line_re(phrase):
    # A fail-fast panic call whose first string argument carries the
    # phrase — literal or generated-literal form, phrase anywhere in
    # the argument (same shape as Rule 3 in check_no_bridges.py).
    return re.compile(
        r'panic\s*\(\s*\\?"[^"]*\b(?:%s)' % phrase, re.I)


SCOPE_RE = _line_re(cnb._SCOPE_PHRASE)
DESUGAR_RE = _line_re(cnb._DESUGAR_PHRASE)


def scan():
    """Live (scope, desugar) counts: {section: {"total": n, "files": {f: n}}}.

    Files are basenames of internal/frontend/synth_*.go, excluding
    EXCLUDED_FILES; only files with a nonzero count appear."""
    sections = {"scope": {"total": 0, "files": {}},
                "desugar": {"total": 0, "files": {}}}
    paths = sorted(glob.glob(os.path.join(SYNTH_DIR, "synth_*.go")))
    if not paths:
        raise SystemExit(
            "check_scope_panic_inventory: no synth_*.go files under %s "
            "(moved synth dir?)" % SYNTH_DIR)
    for path in paths:
        name = os.path.basename(path)
        if name in EXCLUDED_FILES:
            continue
        with open(path) as f:
            for line in f:
                if SCOPE_RE.search(line):
                    section = "scope"
                elif DESUGAR_RE.search(line):
                    section = "desugar"
                else:
                    continue
                sections[section]["total"] += 1
                files = sections[section]["files"]
                files[name] = files.get(name, 0) + 1
    if sections["scope"]["total"] == 0:
        raise SystemExit(
            "check_scope_panic_inventory: zero scope-panic lines found "
            "(regex drift? the scope phrase must match the live tree)")
    return sections


def load_manifest():
    try:
        with open(MANIFEST) as f:
            return json.load(f)
    except FileNotFoundError:
        raise SystemExit(
            "check_scope_panic_inventory: manifest %s missing — run "
            "with --regenerate to create it (and commit it in the same "
            "change)" % MANIFEST)
    except (ValueError, OSError) as e:
        raise SystemExit(
            "check_scope_panic_inventory: manifest %s unparseable: %s"
            % (MANIFEST, e))


def manifest_sections(data):
    try:
        return {"scope": data["scope"], "desugar": data["desugar"]}
    except (KeyError, TypeError):
        raise SystemExit(
            "check_scope_panic_inventory: manifest %s lacks the "
            "'scope'/'desugar' sections" % MANIFEST)


def regenerate():
    sections = scan()
    data = {
        "generated_by": ("python3 .github/scripts/"
                         "check_scope_panic_inventory.py --regenerate"),
        "review": "R23-P1-1 (REVIEW-2026-11-12-23)",
        "definition": (
            "Lines in internal/frontend/synth_*.go matching "
            "panic(\"...<scope|desugar phrase>...\") (literal or "
            "generated-literal form); a line matching both phrases "
            "counts under scope. Archive/mime files are excluded "
            "(see excluded_files)."),
        "excluded_files": sorted(EXCLUDED_FILES),
        "excluded_reason": (
            "Generated by internal/frontend/gen_synth_archive_mime.py; "
            "their multi-result rows are pinned by "
            ".github/scripts/check_mr_table_subset.py. Rule 3 of "
            "check_no_bridges.py still fails on any ADDED scope/desugar "
            "panic in these files."),
        "scope": {"total": sections["scope"]["total"],
                  "files": dict(sorted(sections["scope"]["files"].items()))},
        "desugar": {"total": sections["desugar"]["total"],
                    "files": dict(sorted(sections["desugar"]["files"].items()))},
    }
    with open(MANIFEST, "w") as f:
        json.dump(data, f, indent=2)
        f.write("\n")
    print("check_scope_panic_inventory: regenerated %s "
          "(scope=%d, desugar=%d)"
          % (MANIFEST, data["scope"]["total"], data["desugar"]["total"]))
    return 0


def main(argv):
    if "--regenerate" in argv:
        return regenerate()
    live = scan()
    pinned = manifest_sections(load_manifest())
    problems = []
    for section in ("scope", "desugar"):
        want_files = pinned[section].get("files", {})
        want_total = pinned[section].get("total")
        got_files = live[section]["files"]
        got_total = live[section]["total"]
        if want_total != got_total:
            problems.append(
                "%s total drifted: manifest pins %s, live tree has %s"
                % (section, want_total, got_total))
        for name in sorted(set(want_files) | set(got_files)):
            if want_files.get(name, 0) != got_files.get(name, 0):
                problems.append(
                    "%s/%s: manifest pins %s, live tree has %s"
                    % (section, name, want_files.get(name, 0),
                       got_files.get(name, 0)))
    if problems:
        sys.stderr.write(
            "check_scope_panic_inventory: FAIL (%d problem(s)):\n"
            % len(problems))
        for p in problems:
            sys.stderr.write("  - %s\n" % p)
        sys.stderr.write(
            "If the drift is legitimate (a retirement, a generator "
            "re-run, a newly landed scope), regenerate the manifest "
            "and commit it in the same change:\n"
            "  python3 .github/scripts/check_scope_panic_inventory.py "
            "--regenerate\n")
        return 1
    print("check_scope_panic_inventory: OK "
          "(scope=%d, desugar=%d, %d files pinned)"
          % (live["scope"]["total"], live["desugar"]["total"],
             len(live["scope"]["files"]) + len(live["desugar"]["files"])))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
